public static partial class HindiQuotes
{
    public static class रहलसकतययन
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "जो घूमता नहीं है वो तार्किक नहीं हो सकता, वो उर्ध्वगामी नहीं हो सकता, वो मानवीय नहीं हो सकता। इसलिए हे भावी घुमक्कड़ो! सारी दुनिया तुम्हारा बाहें फैलाये तुम्हारा इंतजार कर रही है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "मैं चाहता हूं तरुणों की भांति तरुणियां भी हजारों की संख्या में विशाल पृथ्वी पर निकल पड़ें और दर्जनों की तादाद में प्रथम श्रेणी की घुमक्कड़ बनें। बड़ा निश्चय करने के पहले वह इस बात को समझ लें कि स्त्री का काम केवल बच्चा पैदा करना नहीं है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "बौद्ध धर्म को दूसरे धर्मों से जो चीज भिन्न बनाती है वो है ईश्वर के अस्तित्व से पूरी तरह इंकार। ईश्वर के आगे-पीछे तो बड़े-बड़े दर्शन खडे़ किए गए, बड़े-बड़े पोथे लिखे गए। दुनिया के सारे धर्म दूसरी बातों में आपस में कट मरें पर ईश्वर, महोवा या अल्लाह के नाम पर सभी सिर नवाए और अक्ल बेच खाने को तैयार हैं। सिर्फ बौद्ध ही ऐसा धर्म है जिसमें ईश्वर के लिए कोई स्थान नहीं है। ईश्वर से मुक्ति पाए बगैर बुद्धि पूरी तरह मुक्त नहीं होती।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "बुद्ध और ईश्वर साथ-साथ नहीं रह सकते। प्रत्यक्ष से इतर किसी अदृश्य ताकत को मैं नहीं मानता।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "जो लोग आज हिन्दुस्तानी जबान की पैरोकारी राजनीतिक कारणों से कर रहे हैं, वे हिंदी-मुसलमान की एकता चाहते हैं जबकि हिन्दी सबसे पुरानी जबान है। हिन्दी 850 ईस्वी से बोली जाती है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "यदि हिन्दी का आगे विकास बढ़ना है तो हिंदी की प्रमुख बोली ‘कौरवी’ को समझना होगा। हिंदी के कथाकारों में जो अधूरा चरित्र-चित्रण मिलता है उसका मुख्य कारण है कौरवी भाषा न समझ पाना। इसलिए हमें वैसे साहित्यकार चाहिए जो लोटा-डोरी लेकर ‘कौरवी’ की तरफ जाएं, ताकि जो हिंदी की लोकोक्तियां हैं, मुहावरें हैं उसको समझ सकें।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "मैंने नाम बदला, वेशभूषा बदली, खान-पान बदला लेकिन हिन्दी के संबंध में मैंने विचारों में कोई परिवर्त्तन नहीं किया।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "हमारी नागरी लिपि दुनिया का सबसे वैज्ञानिक लिपि है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "भाषा और साहित्य, धारा के रूप में चलता है। फर्क इतना ही है कि नदी को हम देश की पृष्ठभूमि में देखते हैं जबकि भाषा, देश और भूमि दोनों की पृष्ठभूमि को लिए आगे बढती है।….. कालक्रम के अनुसार देखने पर ही हमें उसका विकास अधिक सुस्पष्ट रूप से दृष्टिगोचर होता है। ऋग्वेद से लेकर १९वीं सदी के अंत तक की गद्य धारा और काव्य धारा के संग्रहों की आवश्यकता है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "जल्दी ही मुझे मालूम हो गया कि ऐतिहासिक उपन्यासों का लिखना मुझे हाथ में लेना चाहिए….. कारण यह कि अतीत के प्रगतिशील प्रयत्नों को सामने लाकर पाठकों के हृदय में आदर्शों के प्रति प्रेरणा पैदा की जा सकती है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "चौरी-चौरा कांड में शहीद होने वालों का खून देश-माता का चंदन होगा।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "यदि कोई \"गंगा मइया\" की जय बोलने के स्थान पर ’वोल्गा‘ की जय बोलने के लिए कहे, तो मैं इसे पागल का प्रलाप ही कहूँगा।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "धर्मों की जड़ में कुल्हाड़ा लग गया है, और इसलिए अब मजहबों के मेल-मिलाप की बातें भी कभी-कभी सुनने में आती हैं। लेकिन, क्या यह सम्भव है? ‘मजहब नहीं सिखाता आपस में बैर रखना’- इस सफेद झूठ का क्या ठिकाना है? अगर मजहब बैर नहीं सिखलाता तो चोटी-दाढ़ी की लड़ाई में हजार बरस से आज तक हमारा मुल्क पामाल (बर्बाद) क्यों है?असल बात तो यह है कि मजहब तो सिखाता है आपस में बैर रखना। भाई को है सिखाता भाई का खून पीना। हिन्दुस्तानियों की एकता मजहब के मेल पर नहीं होगी, बल्कि मजहबों की चिता पर। कौव्वे को धोकर हंस नहीं बनाया जा सकता। कमली धोकर रंग नहीं चढ़ाया जा सकता। मजहबों की बीमारी स्वाभाविक है। उसकी मौत को छोड़कर इलाज नहीं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "कहने के लिए तो हिन्दुओं पर ताना कसते हुए इस्लाम कहता है कि हमने जात-पांत के बंधनों को तोड़ दिया। इस्लाम में आते ही सब भाई-भाई हो जाते हैं। लेकिन क्या यह बात सच है? यदि ऐसा होता तो आज मोमिन (जुलाहा), अप्सार (धुनिया), राइन (कुंजड़ा) आदि का सवाल न उठता। अर्जल और अशरफ़ का शब्द किसी के मुंह पर न आता। सैयद-शेख़, मलिक-पठान, उसी तरह का ख़्याल अपने से छोटी जातियों से रखते हैं, जैसा कि हिंदुओं के बड़ी जात वाले। खाने के बारे में छूतछात कम है और वह तो अब हिंदुओं में भी कम होता जा रहा है। लेकिन सवाल तो है – सांस्कृतिक और आर्थिक क्षेत्र में इस्लाम की बड़ी जातों ने छोटी जातों को क्या आगे बढ़ने का कभी मौक़ा दिया?", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "जो मजहब अपने नाम पर भाई का खून करने के लिए प्रेरित करता है, उस मजहब पर लानत! जब आदमी चुटिया काट दाढ़ी बढ़ाने भर से मुसलमान और दाढ़ी मुड़ा चुटिया रखने मात्र से हिंदू मालूम होने लगता है, तो इसका मतलब साफ है कि यह भेद सिर्फ बाहरी और बनावटी है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "हमें यह मानने में कोई उज्र हो ही नहीं सकता कि हमारे देश के मुसलमान अपनी जातीयता में मजहब को बहुत स्थान देते हैं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "इस्लाम की समानता और बौद्धों की समानता में बहुत अन्तर है। इस्लाम में मजहबी समानता है। हरेक मुसलमान धर्म-क्षेत्र में समान समझा जाता है, लेकिन बौद्ध धर्म में मानवमात्र समान है – यही क्यों, जीवमात्र समान है। इस मौलिक भेद के कारण एक धर्म युक्तियों, अनुरोध, स्नेह, बन्धुत्व, त्याग, सहिष्णुता से फैला और दूसरा तलवारों की धार पर। वैसे अनेक मुसलमान संतों ने सहिष्णुता और मानव समानता का प्रचार भी किया, पर बहुत कम।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "ये जानते नहीं कि जिहाद का समय बीत चुका है और विज्ञान का युग आ गया है। ये समझते हैं कि इस्लामी छूरेबाजी के बल पर इन्होने पाकिस्तान कायम किया है। उनको यह नहीं मालूम कि अंग्रेजों ने अशगुन पैदा करने के लिए पाकिस्तान को बनाया।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "इस्लाम की सफलता किसी उच्च दार्शनिक विचार, महान सदाचार या भव्य आदर्शवाद के कारण नहीं हुई है। आप कुरान को उठा कर किसी धर्म के प्रमुख ग्रंथ से मिला के देख लीजिए, वह हर तरह से बहुत निम्न कोटि का जँचेगा। ...(इस्लाम की) दूसरी सफलता की कुंजी थी : जैसे भी हो स्त्रियों को रख के उससे औलाद को पैदा कर के बढ़ाना। धर्म प्रचार का इस अनूठे ढंग को आप किसी धर्म के लिए शोभा की बात तो नहीं कह सकते।... एक सांप्रदायिकता दूसरी सांप्रदायिकता को पैदा करती है। मुसलमान इस्लाम को मानें, इसमें कोई आपत्ति नहीं होनी चाहिए, किन्तु यदि वह वेश-भूषा, भाषा, संस्कृति में अपने को विदेशी रखना चाहते हैं, तो समझ लें, यह उनके लिए आफत की चीज है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "मुसलमानों को वही बोली–बानी, वही पर-पोसाक, वही खान-पान अपनाना होगा, जो कि हिंदुओं का है। बिलाइत में ईसाई रहते हैं, यहूदी भी रहते हैं, लेकिन उनको देख के कोई नहीं कह सकता, कि वह दो तीन धर्म को मानते हैं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "एक ईश्वर मानने वाले धर्मों की अपेक्षा अनेक देवता मानने वाले धर्म हज़ार गुना उदार रहे हैं। उनके ईश्वरों की संख्या अपरिमित होने से औरों का भी समावेश आसानी से हो सकता था किंतु एक ईश्वरवादी वैसे करके अपने अकेले ईश्वर की हस्ती को ख़तरे में नहीं डाल सकते थे। आप दुनिया के एक ईश्वरवादी धर्मों के पिछले दो हज़ार वर्ष के इतिहास को देख डालिए, मालूम होगा कि वह सभ्यता, कला, विद्या, विचार-स्वातन्त्र्य और स्वयं मनुष्यों के प्राणों के सबसे बड़े दुश्मन रहे हैं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "जाति-भेद न केवल लोगों को टुकड़े-टुकड़े में बाँट देता है, बल्कि साथ ही यह सबके मन में ऊँच-नीच का भाव पैदा करता है। हमारे पराभव का सारा इतिहास बतलाता है कि हम इसी जाति-भेद के कारण इस अवस्था तक पहुँचे। ये सारी गन्दगियाँ उन्हीं लोगों की तरफ से फैलाई गयी हैं जो धनी हैं या धनी होना चाहते हैं। सबके पीछे ख्याल है धन बटोरकर रख देने या उसकी रक्षा का। गरीबों और अपनी मेहनत की कमाई खाने वालों को ही सबसे ज्यादा नुकसान है, लेकिन सहस्राब्दियों से जात-पाँत के प्रति जनता के अन्दर जो ख्याल पैदा किये गये हैं, वे उन्हें अपनी वास्तविक स्थिति की ओर नजर दौड़ाने नहीं देते। स्वार्थी नेता खुद इसमें सबसे बड़े बाधक हैं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "क्या शक्ल देखकर किसी के बारे में आप बतला सकते हैं कि यह ब्राह्मण है और यह शूद्र? कोयले से भी काले ब्राह्मण आपको लाखों की तादाद में मिलेंगे और शूद्रों में भी गेहुएं रंग वालों का अभाव नहीं है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "कम्युनिस्ट पार्टी की सबसे बड़ी कमजोरी रही कि वे लोग लोकभाषाओं में अपने साहित्य को नहीं ले गए।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "कम्युनिस्ट पार्टी का सदस्य बने बगैर मेरी मृत्यु हो जाती तो मेरा दुभार्ग्य होता।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "जिस दिन भूमि को स्वर्ग में परिणत कर दिया जायगा, उसी दिन आकाश का स्वर्ग ढ़ह पड़ेगा। आकाश-पाताल के स्वर्ग-नर्क को कायम रखने के लिए, उसके नाम पर बाजार चलाने के लिए, जरूरत है, भूमि पर स्वर्ग-नर्क की, राजा-रंक की, दास-स्वामी की।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "हमें अपनी मानसिक दासता की बेड़ी की एक-एक कड़ी को बेदर्दी के साथ तोड़कर फेंकने के लिए तैयार रहना चाहिये। बाहरी क्रान्ति से कहीं ज्यादा जरूरत मानसिक क्रान्ति की है। हमें आगे-पीछे-दाहिने-बांये दोनों हाथों से नंगी तलवारें नचाते हुए अपनी सभी रुढ़ियों को काटकर आगे बढ़ना होगा।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "रूढ़ियों को लोग इसलिए मानते हैं, क्योंकि उनके सामने रूढ़ियों को तोड़ने वालों के उदाहरण पर्याप्त मात्रा में नहीं हैं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "बहुतों ने पवित्र, निराकार, अभौतिक, प्लेटोनिक प्रेम की बड़ी-बड़ी महिमा गाई है और समझाने की कोशिश की है कि स्त्री-पुरुष का प्रेम सात्विक तल पर ही सीमित रह सकता है। लेकिन यह व्याख्या आत्म-सम्मोहन और परवंचना से अधिक महत्व नहीं रखती। यदि कोई यह कहे कि ऋण और धन विद्युत-तरंग मिलकर प्रज्वलित नहीं होंगे, तो यह मानने की बात है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "यदि जनबल पर विश्‍वास है तो हमें निराश होने की आवश्यकता नहीं है। जनता की दुर्दम शक्ति ने, फ़ासिज्म की काली घटाओं में, आशा के विद्युत का संचार किया है। वही अमोघ शक्ति हमारे भविष्य की भी गारण्टी है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "ज़्यादातर पुरानी पोथियों में ७५ प्रतिशत तो बेवकूफियां ही बेवकूफियां भरी पड़ी हैं। हाँ, कहीं कहीं अकल की बातें भी हैं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "इसमें संदेह है कि ऐतिहासिक काल अथवा पिछली सात शताब्दियों में काशी ने कभी देश और राष्ट्र की तत्कालीन या भावी महत्त्वपूर्ण समस्याओं पर माथापच्ची की हो। काशी ने देश को हमेशा पीछे की तरफ खींचने की कोशिश की। एक से एक प्रतिगामी पंडित और परिब्राजकों को उसने प्रदान किया।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "भारतीय दर्शन सांयस या कला का लग्गू-भग्गू न रहा हो, किन्तु धर्म की गुलामी से बदतर गुलामी और क्या हो सकती है?", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "हमारे सामने जो मार्ग है उसका कितना ही भाग बीत चुका है, कुछ हमारे सामने है और बहुत अधिक आनेवाला है। बीते हुए से हम सहायता लेते हैं, आत्म विश्वास प्राप्त करते हैं लेकिन बीते की ओर लौटना प्रगति नहीं, प्रतिगति - पीछे लौटना होगा। हम लौट तो सकते नहीं, क्योंकि अतीत को वर्त्तमान बनाना प्रकृति ने हमारे हाथ में नहीं दे रखा है।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "मैं नहीं चाहता कि आप मेरी मान्यता को ग्रहण करें, किन्तु मैं इतना अवश्य चाहता हूँ कि आप इतिहास के पृष्ठ पलटें। अंग्रेजों द्वारा लिखा गया इतिहास हमारे देश का दूषित, त्रुटित और पक्षपात रंजित इतिहास है। मैं इस इतिहास पर सिद्ध साहित्य को नहीं परखता। क्या आप बता सकते हैं कि सिद्धों की विशाल परंपरा से कौन सा अंग्रेज़ इतिहासकार परिचित है? किसने पूर्व–मध्य युग पर प्रामाणिक दृष्टि से लिखा है। आप इन इतिहास ग्रन्थों को पढ़ कर कण्णपा या किसी सिद्ध या नाथपंथी योगी का परिचय नहीं पा सकते क्योंकि इनकी दृष्टि सन-सम्वतों में सिमटी रह जाती है। मैं देखता हूँ कि गौतम बुद्ध के बाद देश में तीन-चार बार क्रांतियाँ हुई हैं। किन्तु किसी क्रांति को जनमानस की व्यापक क्रांति के रूप में हमारे इतिहास लेखकों ने अंकित नहीं किया। महेशों और नरेशों का इतिहास लिखने वाले क्या जानें कि जनमानस को जागृत करने वाले विलासी नरेश नहीं होते, साधु, महात्मा और सिद्ध होते हैं। जो राज्य सत्ता से कहीं अधिक प्रभाव जनता पर डालते हैं। आप लोग पहले इतिहास की दृष्टि को स्वच्छ करें, इतिहास के पृष्ठों पर पड़ी धूल को साफ करें और तब इतिहास पढ़ने का उपक्रम करें। मैं सिद्धों और नाथों का समर्थक नहीं हूँ किन्तु इतिहास में उनके महत्त्व की कथाओं को पा कर यह कहने को बाध्य हुआ हूँ।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "सेठों के सामने अब राजा झूठे हैं। उनके खर्च बहुत बढ़ गए हैं, लेकिन आमदनी उतनी की उतनी ही है, और सेठों के लिए आमदनी की कोई सीमा नहीं।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "त्रिपिटक में कुछ अधिक प्रवेश करते ही वेद, ईश्वर और आर्यसमाज ने साथ छोड़ दिया, मैं अनीश्वरवादी नास्तिक बन गया। बुद्ध और उनकी शिक्षाओं के प्रति मेरा अनुराग हो गया। उसके बाद तो कोई धर्म मुझे आकृष्ट नहीं कर सका। बुद्ध से अगली मंजिल में मार्क्स मुझे मिले। भौतिकवाद मेरा दर्शन हो गया। पर, बुद्ध के मधुर व्यक्तित्व का आकर्षण मेरे मन से कभी नहीं गया।", Author = "राहुल सांकृत्यायन" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/राहुल_सांकृत्यायन", Text = "कोई समय था कि जब मैं धर्मप्रचारक बनने का तीव्र अनुरागी था, लेकिन अब अवस्था बिल्कुल बदल गयी थी। बौद्धधर्म के साथ भी मेरा कच्चे धागे का ही सम्बन्ध था। हाँ बुद्ध के प्रति मेरी श्रद्धा कभी कम नहीं हुई। मैं उन्हें भारत का सबसे बड़ा विचारक मानता रहा हूँ और मैं समझता हूँ कि जिस वक्त दुनिया के धर्म का नामोनिशान न रह जायगा, उस वक्त भी लोग बड़े सम्मान के साथ बुद्ध का नाम लेंगे।", Author = "राहुल सांकृत्यायन" },
        };
    }
}